<div class="welcome"><div><h2>Ringkasan operasional</h2><p>Status inventaris dan pekerjaan tim hari ini.</p></div><a class="btn primary" href="/tugas/create">Buat tugas</a></div>
<div class="stats"><a class="stat" href="/pc"><span class="stat-icon green"><?=simit_icon('pc')?></span><div><small>Total PC</small><strong><?=$stats['pc']?></strong><em>aset aktif</em></div></a><a class="stat" href="/pc?q=servis"><span class="stat-icon amber"><?=simit_icon('pemeriksaan')?></span><div><small>Perlu perhatian</small><strong><?=$stats['problem']?></strong><em>perangkat</em></div></a><a class="stat" href="/perangkat"><span class="stat-icon blue"><?=simit_icon('perangkat')?></span><div><small>Perangkat lain</small><strong><?=$stats['units']?></strong><em>total unit</em></div></a><a class="stat" href="/tugas"><span class="stat-icon purple"><?=simit_icon('tugas')?></span><div><small>Tugas terbuka</small><strong><?=$stats['open_tasks']?></strong><em>perlu tindak lanjut</em></div></a></div>
<style>.task-row.clickable,.attention.clickable{cursor:pointer;border-radius:12px;transition:.18s ease}.task-row.clickable:hover,.attention.clickable:hover{background:rgba(37,131,59,.07);transform:translateX(3px)}</style><script>document.addEventListener('DOMContentLoaded',()=>{const taskIds=<?=json_encode(array_column($tasks,'id'))?>;document.querySelectorAll('.task-row').forEach((row,i)=>{row.classList.add('clickable');row.tabIndex=0;const go=()=>location.href='/tugas/hasil/'+taskIds[i];row.addEventListener('click',go);row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}})});const attention=<?=json_encode(array_map(fn($a)=>['id'=>$a['id'],'type'=>$a['type']],$attention))?>;document.querySelectorAll('.attention').forEach((row,i)=>{row.classList.add('clickable');row.tabIndex=0;const go=()=>location.href='/'+(attention[i].type==='PC'?'pc':'perangkat')+'/edit/'+attention[i].id;row.addEventListener('click',go);row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}})})});</script>
<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h3>Tugas prioritas</h3><p>Pekerjaan yang perlu segera ditindaklanjuti.</p></div><a href="/tugas">Lihat semua</a></div><div class="task-list"><?php foreach($tasks as $t):?><article class="task-row"><span class="priority <?=strtolower($t['priority'])?>"></span><div><strong><?=e($t['title'])?></strong><small><?=e($t['number'])?> · <?=e($t['assignee']?:'Belum ada PIC')?></small></div><span class="badge"><?=e($t['status'])?></span></article><?php endforeach;?><?php if(!$tasks):?><div class="empty">Tidak ada tugas terbuka.</div><?php endif;?></div></section><section class="panel"><div class="panel-head"><div><h3>Perlu perhatian</h3><p>Temuan kondisi perangkat terbaru.</p></div><a href="/perangkat">Tinjau</a></div><?php if($attention):foreach($attention as $a):?><article class="attention"><span class="stat-icon amber"><?=simit_icon('pemeriksaan')?></span><div><strong><?=e($a['name'])?></strong><small><?=e($a['location']??'-')?> · <?=e($a['notes']??'Tanpa catatan')?></small></div><span class="badge danger"><?=e($a['status'])?></span></article><?php endforeach;else:?><div class="healthy"><span><?=simit_icon('audit')?></span><strong>Semua perangkat terpantau</strong><p>Belum ada perangkat berstatus rusak atau perlu servis.</p></div><?php endif;?></section></div>

